<template>
  <div class="page-stack">
    <PageHeader :title="title" :description="description"><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button><el-button type="primary" :icon="Plus" @click="openCreate">添加推荐</el-button></PageHeader>
    <el-card shadow="never" class="recommend-card">
      <div class="filter-row"><el-input v-model="keyword" clearable :placeholder="`搜索${targetLabel}名称`" :prefix-icon="Search" @keyup.enter="load"/><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option label="已推荐" :value="1"/><el-option label="未推荐" :value="0"/></el-select><el-button type="primary" :icon="Search" @click="load">查询</el-button><el-button :icon="RefreshLeft" @click="reset">重置</el-button><span class="record-total">共 {{ total }} 条</span></div>
      <el-table v-loading="loading" :data="rows" row-key="id" @selection-change="selectedRows=$event">
        <el-table-column type="selection" width="48"/>
        <el-table-column label="推荐内容" min-width="250"><template #default="{ row }"><div class="recommend-item"><el-image v-if="mode==='brand'" :src="row.brandLogo" fit="cover"><template #error><span>品</span></template></el-image><span class="item-copy"><b>{{ row[displayField] || '未命名内容' }}</b><small>{{ targetLabel }}编号 {{ row[sourceIdField] || '—' }}</small></span></div></template></el-table-column>
        <el-table-column label="推荐位置" width="130"><template #default="{ row }"><el-tag effect="plain" :type="Number(row.recommendStatus)===1?'success':'info'">{{ Number(row.recommendStatus)===1?'展示中':'未展示' }}</el-tag></template></el-table-column>
        <el-table-column label="排序" width="150"><template #default="{ row }"><div class="sort-control"><el-input-number v-model="row.sort" size="small" :min="0" :max="9999" controls-position="right"/><el-button link type="primary" @click="saveSort(row)">保存</el-button></div></template></el-table-column>
        <el-table-column label="操作" width="190" fixed="right"><template #default="{ row }"><el-switch :model-value="Number(row.recommendStatus)" :active-value="1" :inactive-value="0" @change="(value:string|number|boolean)=>changeStatus([row.id],Number(value))"/><el-popconfirm title="从首页推荐中移除这条内容？" @confirm="remove([row.id])"><template #reference><el-button link type="danger">移除</el-button></template></el-popconfirm></template></el-table-column>
        <template #empty><el-empty :description="`暂无${targetLabel}推荐`" :image-size="82"><el-button type="primary" @click="openCreate">添加推荐内容</el-button></el-empty></template>
      </el-table>
      <div class="table-footer"><span v-if="selectedRows.length">已选 {{ selectedRows.length }} 条</span><div><el-button size="small" :disabled="!selectedRows.length" @click="changeStatus(selectedRows.map(item=>item.id),0)">批量取消推荐</el-button><el-button size="small" type="primary" :disabled="!selectedRows.length" @click="changeStatus(selectedRows.map(item=>item.id),1)">批量设为推荐</el-button></div><el-pagination v-model:current-page="pageNum" v-model:page-size="pageSize" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @change="load"/></div>
    </el-card>
    <el-dialog v-model="visible" :title="`添加${targetLabel}推荐`" width="560px">
      <el-form label-position="top"><el-form-item :label="`选择${targetLabel}`"><el-select v-model="selectedIds" multiple filterable collapse-tags collapse-tags-tooltip :placeholder="`选择要推荐的${targetLabel}`" style="width:100%"><el-option v-for="item in options" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item></el-form>
      <div class="recommend-help">可多选，保存后会加入首页推荐列表；具体展示顺序可在列表中调整。</div>
      <template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!selectedIds.length" @click="create">添加到首页</el-button></template>
    </el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Plus, Refresh, RefreshLeft, Search } from '@element-plus/icons-vue'
import PageHeader from '@/components/PageHeader.vue'
import { getBrandList, getProductList } from '@/api/product'
import { request } from '@/utils/request'
const route=useRoute();const mode=computed(()=>route.path.endsWith('home-brand')?'brand':route.path.endsWith('new-product')?'new':route.path.endsWith('hot-product')?'hot':'subject');const title=computed(()=>({brand:'品牌推荐',new:'新品推荐',hot:'人气推荐',subject:'专题推荐'} as Record<string,string>)[mode.value]);const description=computed(()=>`配置首页${targetLabel.value}展示内容、推荐状态和排序。`);const targetLabel=computed(()=>mode.value==='brand'?'品牌':mode.value==='subject'?'专题':'商品');const displayField=computed(()=>mode.value==='brand'?'brandName':mode.value==='subject'?'subjectName':'productName');const sourceIdField=computed(()=>mode.value==='brand'?'brandId':mode.value==='subject'?'subjectId':'productId');const base=computed(()=>mode.value==='brand'?'/mall-admin/home/brand':mode.value==='new'?'/mall-admin/home/newProduct':mode.value==='hot'?'/mall-admin/home/recommendProduct':'/mall-admin/home/recommendSubject');const queryField=computed(()=>mode.value==='brand'?'brandName':mode.value==='subject'?'subjectName':'productName')
const rows=ref<Record<string,any>[]>([]);const selectedRows=ref<Record<string,any>[]>([]);const options=ref<{id:number;name:string}[]>([]);const selectedIds=ref<number[]>([]);const keyword=ref('');const status=ref<number>();const total=ref(0);const pageNum=ref(1);const pageSize=ref(10);const loading=ref(false);const saving=ref(false);const visible=ref(false)
async function load(){loading.value=true;try{const data=await request<{list:Record<string,any>[];total:number}>({url:`${base.value}/list`,method:'get',params:{pageNum:pageNum.value,pageSize:pageSize.value,[queryField.value]:keyword.value.trim()||undefined,recommendStatus:status.value}});rows.value=data.list||[];total.value=Number(data.total)||0}finally{loading.value=false}}
function reset(){keyword.value='';status.value=undefined;pageNum.value=1;load()}
async function openCreate(){selectedIds.value=[];visible.value=true;if(mode.value==='brand'){const data=await getBrandList({pageNum:1,pageSize:500});options.value=(data.list||[]).map(item=>({id:item.id,name:item.name}))}else if(mode.value==='subject'){options.value=await request<{id:number;title?:string;name?:string}[]>({url:'/mall-admin/subject/listAll',method:'get'}).then(items=>items.map(item=>({id:item.id,name:item.title||item.name||`专题 #${item.id}`})))}else{const data=await getProductList({pageNum:1,pageSize:500,keyword:''});options.value=(data.list||[]).map(item=>({id:item.id,name:item.name||`商品 #${item.id}`}))}}
async function create(){saving.value=true;try{const rows=selectedIds.value.map((id,index)=>({[sourceIdField.value]:id,recommendStatus:1,sort:index}));await request({url:`${base.value}/create`,method:'post',data:rows});ElMessage.success(`已添加 ${rows.length} 条首页推荐`);visible.value=false;await load()}finally{saving.value=false}}
async function changeStatus(ids:number[],recommendStatus:number){await request({url:`${base.value}/update/recommendStatus`,method:'post',params:{ids:ids.join(','),recommendStatus}});ElMessage.success('推荐状态已更新');selectedRows.value=[];await load()}
async function remove(ids:number[]){await request({url:`${base.value}/delete`,method:'post',params:{ids:ids.join(',')}});ElMessage.success('已从推荐中移除');await load()}
async function saveSort(row:Record<string,any>){await request({url:`${base.value}/update/sort/${row.id}`,method:'post',params:{sort:row.sort}});ElMessage.success('推荐顺序已保存')}
watch(mode,()=>{pageNum.value=1;keyword.value='';status.value=undefined;load()});onMounted(load)
</script>
<style scoped>
.recommend-card{border-color:#e4ebf5;border-radius:10px}.recommend-card :deep(.el-card__body){padding:16px 18px}.filter-row{display:flex;align-items:center;gap:9px;margin-bottom:14px}.filter-row .el-input{width:245px}.filter-row .el-select{width:145px}.record-total{margin-left:auto;color:#909baa;font-size:10px}.recommend-item{display:flex;align-items:center;gap:10px}.recommend-item :deep(.el-image){display:grid;width:43px;height:43px;flex:0 0 43px;place-items:center;border:1px solid #e9edf2;border-radius:5px;color:#8290a4;background:#f4f6f9}.item-copy{display:grid;gap:4px}.item-copy b{color:#3b495d;font-size:11px}.item-copy small{color:#939eac;font-size:9px}.sort-control{display:flex;align-items:center;gap:5px}.sort-control :deep(.el-input-number){width:91px}.table-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-top:15px;color:#8c97a6;font-size:10px}.table-footer>div{display:flex;gap:6px;margin-right:auto}.recommend-help{padding:10px 12px;border-radius:6px;color:#778599;background:#f4f7fb;font-size:10px}@media(max-width:740px){.filter-row{flex-wrap:wrap}.filter-row .el-input{width:100%}.table-footer{align-items:flex-start;flex-direction:column}.table-footer>div{margin-right:0}.table-footer :deep(.el-pagination){max-width:100%;overflow:auto}}
</style>
